INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7289727, 1136202, 57447, '<td valign="top">I like the angle you chose to shoot this.</td>', 'I like the angle you chose to shoot this.', '2014-12-03 20:45:03.000000', NULL, 1),
(7289728, 1136155, 57447, '<td valign="top">Ha!  Nice!</td>', 'Ha!  Nice!', '2014-12-03 20:45:19.000000', NULL, 1),
(7289797, 1135078, 30364, '<td valign="top">Yes, that''s good stuff.  Sidesteps all the usual mind-numbing constrictions of ''good'' photography, and arrives deftly at a good photograph; at an interesting, dynamic photograph.  It''s one of those contrary pictures that thumbs its nose at convention and carries it off comfortably. 8.  Thank you.</td>', 'Yes, that''s good stuff.  Sidesteps all the usual mind-numbing constrictions of ''good'' photography, and arrives deftly at a good photograph; at an interesting, dynamic photograph.  It''s one of those contrary pictures that thumbs its nose at convention and carries it off comfortably. 8.  Thank you.', '2014-12-04 10:56:55.000000', NULL, 1),
(7289798, 1136495, 30364, '<td valign="top">It''s a quite beautiful thing, this photograph.  The relative weight, one side versus the other, animates the bird, the picture as a whole, and the imagination.  9. Thank you.</td>', 'It''s a quite beautiful thing, this photograph.  The relative weight, one side versus the other, animates the bird, the picture as a whole, and the imagination.  9. Thank you.', '2014-12-04 11:00:14.000000', NULL, 1),
(7289801, 1135581, 30364, '<td valign="top">Very nice photograph that''s more complex with each moment''s appreciation.  The girl and her guardian are the obvious play of course, but the supporting cast are all right on their marks, adding another layer of pleasure for the viewer.  Imagine if any one of the minor players (including the flags) was in a different spot, or doing something else other than what they are doing.  The photograph would be diminished.  But they aren''t, and it isn''t.  9. Thank you.</td>', 'Very nice photograph that''s more complex with each moment''s appreciation.  The girl and her guardian are the obvious play of course, but the supporting cast are all right on their marks, adding another layer of pleasure for the viewer.  Imagine if any one of the minor players (including the flags) was in a different spot, or doing something else other than what they are doing.  The photograph would be diminished.  But they aren''t, and it isn''t.  9. Thank you.', '2014-12-04 11:16:48.000000', NULL, 1),
(7289804, 1136481, 30364, '<td valign="top">If all botanicals were as interesting and absorbing as this, I''d be a lot more appreciative of the genre.  What a beautiful, captivating image this is! 9. Thank you.</td>', 'If all botanicals were as interesting and absorbing as this, I''d be a lot more appreciative of the genre.  What a beautiful, captivating image this is! 9. Thank you.', '2014-12-04 11:20:55.000000', NULL, 1),
