(7290596, 1136432, 13077, '<td valign="top">Bunch of characters. lol. Lots of cheerfulness and energy in this one.</td>', 'Bunch of characters. lol. Lots of cheerfulness and energy in this one.', '2014-12-07 11:53:14.000000', NULL, 1),
(7290598, 1136099, 13077, '<td valign="top">Nice photo (actually I think it would make a good postcard for the place you shot it), but is there a reason it''s so small when we can use 1200 pixels now?</td>', 'Nice photo (actually I think it would make a good postcard for the place you shot it), but is there a reason it''s so small when we can use 1200 pixels now?', '2014-12-07 11:54:22.000000', NULL, 1),
(7290600, 1136427, 13077, '<td valign="top">LOL - nicely captured. I know the feeling.</td>', 'LOL - nicely captured. I know the feeling.', '2014-12-07 11:54:48.000000', NULL, 1),
(7290601, 1135996, 13077, '<td valign="top">It has an uneasiness to it, also a sense of mystery like something strange is about to happen.</td>', 'It has an uneasiness to it, also a sense of mystery like something strange is about to happen.', '2014-12-07 11:55:36.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7290602, 1136357, 13077, '<td valign="top">Very cool lizard and great detail, also the shallow DOF does a great job of keeping the background from distracting from the subject.</td>', 'Very cool lizard and great detail, also the shallow DOF does a great job of keeping the background from distracting from the subject.', '2014-12-07 11:56:28.000000', NULL, 1),
(7290603, 1135870, 13077, '<td valign="top">Nicely done. A very stately looking animal.</td>', 'Nicely done. A very stately looking animal.', '2014-12-07 11:56:45.000000', NULL, 1),
(7290604, 1136049, 13077, '<td valign="top">Oh wow. I like the way it''s simple and very complex at the same time.</td>', 'Oh wow. I like the way it''s simple and very complex at the same time.', '2014-12-07 11:57:09.000000', NULL, 1),
(7290605, 1136169, 13077, '<td valign="top">Great sky, and well positioned to use the piers and docks to add some interesting silhouettes.</td>', 'Great sky, and well positioned to use the piers and docks to add some interesting silhouettes.', '2014-12-07 11:57:45.000000', NULL, 1),
(7290607, 1136472, 13077, '<td valign="top">Such a cool looking place, wonder where it is. Great touch with the guy going up.</td>', 'Such a cool looking place, wonder where it is. Great touch with the guy going up.', '2014-12-07 11:58:13.000000', NULL, 1),
(7290608, 1135594, 13077, '<td valign="top">Beautiful scene and light.</td>', 'Beautiful scene and light.', '2014-12-07 11:58:31.000000', NULL, 1),
(7290610, 1136461, 13077, '<td valign="top">The early birds have been getting the worms for an hour, now I''m ready to go catch the late birds!</td>', 'The early birds have been getting the worms for an hour, now I''m ready to go catch the late birds!', '2014-12-07 11:59:05.000000', NULL, 1),
(7290611, 1135952, 13077, '<td valign="top">Very nice composition, the foreground rocks look great and the sky is very dramatic. Well exposed too.</td>', 'Very nice composition, the foreground rocks look great and the sky is very dramatic. Well exposed too.', '2014-12-07 11:59:39.000000', NULL, 1),
(7290612, 1136344, 13077, '<td valign="top">Nice moment and good shot of both of the dogs.</td>', 'Nice moment and good shot of both of the dogs.', '2014-12-07 12:00:02.000000', NULL, 1),
(7290613, 1136455, 13077, '<td valign="top">Nicely caught action, good composition and I like the flying dirt.</td>', 'Nicely caught action, good composition and I like the flying dirt.', '2014-12-07 12:00:33.000000', NULL, 1),
(7290614, 1136454, 13077, '<td valign="top">Kudos, little bird</td>', 'Kudos, little bird', '2014-12-07 12:00:48.000000', NULL, 1),
(7290615, 1135424, 13077, '<td valign="top">Cool use of the camera tilt with this one. So many angles and shapes, and although it''s represented fairly literally, the tilt and distortion bring some abstractness to it so we can appreciate the shapes.</td>', 'Cool use of the camera tilt with this one. So many angles and shapes, and although it''s represented fairly literally, the tilt and distortion bring some abstractness to it so we can appreciate the shapes.', '2014-12-07 12:02:17.000000', NULL, 1),
(7290616, 1136495, 13077, '<td valign="top">Soft and simple, has a peaceful and relaxing vibe.</td>', 'Soft and simple, has a peaceful and relaxing vibe.', '2014-12-07 12:02:41.000000', NULL, 1),
(7290617, 1135434, 13077, '<td valign="top">Nicely caught tide and interesting sky.</td>', 'Nicely caught tide and interesting sky.', '2014-12-07 12:03:18.000000', NULL, 1),
(7290619, 1136346, 13077, '<td valign="top">I like this a lot. Stages of life, and we lose the wonder and excitement day by day.</td>', 'I like this a lot. Stages of life, and we lose the wonder and excitement day by day.', '2014-12-07 12:04:10.000000', NULL, 1),
(7290620, 1136202, 13077, '<td valign="top">Makes me think of the TV cooking shows... "it''s RAW! it''s f''ing RAW! you''re going home!"</td>', 'Makes me think of the TV cooking shows... "it''s RAW! it''s f''ing RAW! you''re going home!"', '2014-12-07 12:05:16.000000', NULL, 1),
(7290621, 1135824, 13077, '<td valign="top">Very impressive animal. He looks pretty old, must have good ears to have lived that long.</td>', 'Very impressive animal. He looks pretty old, must have good ears to have lived that long.', '2014-12-07 12:06:10.000000', NULL, 1),
(7290622, 1136128, 13077, '<td valign="top">Looks like a nice enough place to read.</td>', 'Looks like a nice enough place to read.', '2014-12-07 12:06:35.000000', NULL, 1),
(7290623, 1135971, 13077, '<td valign="top">Very cool. The angles of the aurora complement the hillside well, and good color balance to keep an overall cool temperature in the dark sky and stars. Is that smoke from someone''s campfire on the left?</td>', 'Very cool. The angles of the aurora complement the hillside well, and good color balance to keep an overall cool temperature in the dark sky and stars. Is that smoke from someone''s campfire on the left?', '2014-12-07 12:08:08.000000', NULL, 1),
(7290624, 1135407, 13077, '<td valign="top">Nice - the world just got more exciting!</td>', 'Nice - the world just got more exciting!', '2014-12-07 12:08:52.000000', NULL, 1),
(7290625, 1136211, 13077, '<td valign="top">The exposure time and composition are good, but it looks a little soft overall. Not sure if it was a focus issue or camera shake, though.</td>', 'The exposure time and composition are good, but it looks a little soft overall. Not sure if it was a focus issue or camera shake, though.', '2014-12-07 12:10:14.000000', NULL, 1),
(7290626, 1136010, 13077, '<td valign="top">Nicely prepared scene, but I think moving to the right a little to keep the bottles visually separate from the glass would have made it more attractive.</td>', 'Nicely prepared scene, but I think moving to the right a little to keep the bottles visually separate from the glass would have made it more attractive.', '2014-12-07 12:10:54.000000', NULL, 1),
(7290627, 1136313, 13077, '<td valign="top">She drew an ass! lol<br/>Nice catch, she looks like she''s having fun drawing.</td>', 'She drew an ass! lolNice catch, she looks like she''s having fun drawing.', '2014-12-07 12:11:39.000000', NULL, 1),
(7290628, 1136189, 13077, '<td valign="top">Feed one, gotta feed ''em all huh. Nicely captured and good focus on the birds and people.</td>', 'Feed one, gotta feed ''em all huh. Nicely captured and good focus on the birds and people.', '2014-12-07 12:12:16.000000', NULL, 1),
(7290630, 1136143, 13077, '<td valign="top">Looks like a nice peaceful place.</td>', 'Looks like a nice peaceful place.', '2014-12-07 12:12:40.000000', NULL, 1),
(7290631, 1135143, 13077, '<td valign="top">The eye contact on this one is great.</td>', 'The eye contact on this one is great.', '2014-12-07 12:13:28.000000', NULL, 1),
(7290632, 1135340, 13077, '<td valign="top">Nicely done - seeing the sharp details in the water is cool, it''s well composed and the sky is interesting, and you captured the mist well.</td>', 'Nicely done - seeing the sharp details in the water is cool, it''s well composed and the sky is interesting, and you captured the mist well.', '2014-12-07 12:14:12.000000', NULL, 1),
(7290633, 1136341, 13077, '<td valign="top">Sorry but I don''t find this to be an interesting or compelling photo.</td>', 'Sorry but I don''t find this to be an interesting or compelling photo.', '2014-12-07 12:21:27.000000', NULL, 1),
(7290634, 1136200, 13077, '<td valign="top">Nice candid shot - well focused and composed, good tones and good moment.</td>', 'Nice candid shot - well focused and composed, good tones and good moment.', '2014-12-07 12:21:48.000000', NULL, 1),
(7290635, 1136162, 13077, '<td valign="top">Super cool detail in the foreground here, and of course a very cool sky.</td>', 'Super cool detail in the foreground here, and of course a very cool sky.', '2014-12-07 12:22:29.000000', NULL, 1),
(7290636, 1136444, 13077, '<td valign="top">Interesting scene and I like how the light plays on the shaded water vs. the water in the sun.</td>', 'Interesting scene and I like how the light plays on the shaded water vs. the water in the sun.', '2014-12-07 12:23:06.000000', NULL, 1),
(7290637, 1135122, 13077, '<td valign="top">Very cool bird, and nicely captured.</td>', 'Very cool bird, and nicely captured.', '2014-12-07 12:23:18.000000', NULL, 1),
(7290638, 1136416, 13077, '<td valign="top">Aww. Nicely caught moment.</td>', 'Aww. Nicely caught moment.', '2014-12-07 12:23:29.000000', NULL, 1),
(7290640, 1136425, 13077, '<td valign="top">Gritty, hard and un-glamorously emotive.</td>', 'Gritty, hard and un-glamorously emotive.', '2014-12-07 12:24:16.000000', NULL, 1),
(7290641, 1136465, 13077, '<td valign="top">I don''t think this one turned out as well as it could have. Either more blur or less, maybe.</td>', 'I don''t think this one turned out as well as it could have. Either more blur or less, maybe.', '2014-12-07 12:24:56.000000', NULL, 1),
(7290642, 1134946, 13077, '<td valign="top">Interesting use of negative space and the tones have an old-fashioned vibe. Like the negative space would be used for ad text.<br/>A good portrait, nicely posed and good eye contact.</td>', 'Interesting use of negative space and the tones have an old-fashioned vibe. Like the negative space would be used for ad text.A good portrait, nicely posed and good eye contact.', '2014-12-07 12:26:08.000000', NULL, 1),
(7290643, 1136463, 13077, '<td valign="top">Very nice. Full of detail and nice tones. Super cool sky.</td>', 'Very nice. Full of detail and nice tones. Super cool sky.', '2014-12-07 12:26:39.000000', NULL, 1),
(7290644, 1136251, 13077, '<td valign="top">Excellent details and sort of gloomy but bright at the same time colors. A good environmental portrait, great eye contact and well composed.</td>', 'Excellent details and sort of gloomy but bright at the same time colors. A good environmental portrait, great eye contact and well composed.', '2014-12-07 12:27:55.000000', NULL, 1),
(7290645, 1135581, 13077, '<td valign="top">Cute. Nicely captured moment and well exposed/processed for the environment textures and details. Sure looks cold.</td>', 'Cute. Nicely captured moment and well exposed/processed for the environment textures and details. Sure looks cold.', '2014-12-07 12:29:46.000000', NULL, 1),
(7290646, 1136328, 13077, '<td valign="top">Very nice. I like the variety of color temperatures from the lights of the city.</td>', 'Very nice. I like the variety of color temperatures from the lights of the city.', '2014-12-07 12:30:21.000000', NULL, 1),
(7290647, 1136449, 13077, '<td valign="top">Uh oh, the model from the Chairs challenge didn''t make it out alive? lol</td>', 'Uh oh, the model from the Chairs challenge didn''t make it out alive? lol', '2014-12-07 12:31:22.000000', NULL, 1),
(7290649, 1136393, 13077, '<td valign="top">A visually striking place and an interesting look into their lives, and I like that each of the ''characters'' is going about their business like the camera isn''t there. Overall, I like it a lot.</td>', 'A visually striking place and an interesting look into their lives, and I like that each of the ''characters'' is going about their business like the camera isn''t there. Overall, I like it a lot.', '2014-12-07 12:41:48.000000', NULL, 1),
(7290650, 1136168, 13077, '<td valign="top">It works well visually, but there are some technical quality issues with it.</td>', 'It works well visually, but there are some technical quality issues with it.', '2014-12-07 12:42:26.000000', NULL, 1),
(7290653, 1135407, 147247, '<td valign="top">Soooooooo cute!</td>', 'Soooooooo cute!', '2014-12-07 13:08:20.000000', NULL, 1),
(7290670, 1136220, 30861, '<td valign="top">Hiya Meggye! And new-lights Wendy!</td>', 'Hiya Meggye! And new-lights Wendy!', '2014-12-07 15:48:43.000000', NULL, 1),
(7290671, 1136333, 96574, '<td valign="top">Amazing, my pick for the blue. On an entirely different level than all the other entries this month.</td>', 'Amazing, my pick for the blue. On an entirely different level than all the other entries this month.', '2014-12-07 16:18:55.000000', NULL, 1),
(7290674, 1136365, 13077, '<td valign="top">Very detailed, I like the variety of textures in the land, water and sky.</td>', 'Very detailed, I like the variety of textures in the land, water and sky.', '2014-12-07 16:46:40.000000', NULL, 1),
(7290675, 1136409, 13077, '<td valign="top">Cool point of view. From a drone maybe?</td>', 'Cool point of view. From a drone maybe?', '2014-12-07 16:46:55.000000', NULL, 1),
(7290676, 1136110, 13077, '<td valign="top">It''s getting away!</td>', 'It''s getting away!', '2014-12-07 16:47:06.000000', NULL, 1),
(7290677, 1136441, 13077, '<td valign="top">Nicely framed with the trees and mist near the top of the picture - well done. I like the look of the tones too.</td>', 'Nicely framed with the trees and mist near the top of the picture - well done. I like the look of the tones too.', '2014-12-07 16:47:37.000000', NULL, 1),
(7290678, 1136112, 13077, '<td valign="top">It looks unusual with her sunglasses on like that, like she''s a real life cartoon duck or something.</td>', 'It looks unusual with her sunglasses on like that, like she''s a real life cartoon duck or something.', '2014-12-07 16:48:06.000000', NULL, 1),
(7290679, 1136155, 13077, '<td valign="top">Get em!<br/>Nicely captured action.</td>', 'Get em!Nicely captured action.', '2014-12-07 16:48:16.000000', NULL, 1),
