(7290681, 1136470, 13077, '<td valign="top">Very cool architecture, and well shot. Good time of day as the shadows work to your advantage and the cloud reflections are good.</td>', 'Very cool architecture, and well shot. Good time of day as the shadows work to your advantage and the cloud reflections are good.', '2014-12-07 16:49:03.000000', NULL, 1),
