(7290683, 1136372, 13077, '<td valign="top">Nicely done - the background is very pleasing and unobtrusive, the details in the fence and post are nice and the bird is sharp and well posed.</td>', 'Nicely done - the background is very pleasing and unobtrusive, the details in the fence and post are nice and the bird is sharp and well posed.', '2014-12-07 16:49:54.000000', NULL, 1),
(7290684, 1135781, 13077, '<td valign="top">Impressive looking bear for sure.</td>', 'Impressive looking bear for sure.', '2014-12-07 16:50:10.000000', NULL, 1),
(7290685, 1136448, 13077, '<td valign="top">Nicely captured - good and sharp and the light shining in his eye is nice.</td>', 'Nicely captured - good and sharp and the light shining in his eye is nice.', '2014-12-07 16:50:36.000000', NULL, 1),
(7290686, 1136349, 13077, '<td valign="top">Very cool tones, especially of the rocky hills in the distance.</td>', 'Very cool tones, especially of the rocky hills in the distance.', '2014-12-07 16:51:08.000000', NULL, 1),
(7290688, 1136481, 13077, '<td valign="top">This is cool - abstract with a little reality thrown in.</td>', 'This is cool - abstract with a little reality thrown in.', '2014-12-07 16:51:27.000000', NULL, 1),
(7290689, 1136279, 13077, '<td valign="top">Very interesting place, and a great point of view. Well processed too, and a perfect exposure time.</td>', 'Very interesting place, and a great point of view. Well processed too, and a perfect exposure time.', '2014-12-07 16:52:09.000000', NULL, 1),
(7290690, 1136282, 13077, '<td valign="top">She doesn''t look thrilled about her job, but hey.</td>', 'She doesn''t look thrilled about her job, but hey.', '2014-12-07 16:52:32.000000', NULL, 1),
(7290691, 1135472, 13077, '<td valign="top">A nice scene, but a little soft. Might have been camera shake.</td>', 'A nice scene, but a little soft. Might have been camera shake.', '2014-12-07 16:52:52.000000', NULL, 1),
(7290692, 1136380, 13077, '<td valign="top">Good use of the water to catch the reflections, and I like the few colorful clouds in the sky too.</td>', 'Good use of the water to catch the reflections, and I like the few colorful clouds in the sky too.', '2014-12-07 16:53:14.000000', NULL, 1),
(7290693, 1136436, 13077, '<td valign="top">The dark overall tone works for this guy.</td>', 'The dark overall tone works for this guy.', '2014-12-07 16:53:35.000000', NULL, 1),
(7290694, 1135761, 13077, '<td valign="top">A good looking scene, but the glow added by the processing is distracting in my opinion.</td>', 'A good looking scene, but the glow added by the processing is distracting in my opinion.', '2014-12-07 16:54:12.000000', NULL, 1),
(7290695, 1136421, 13077, '<td valign="top">Very joyful. I like the red balloon in contrast to the mainly green other tones.</td>', 'Very joyful. I like the red balloon in contrast to the mainly green other tones.', '2014-12-07 16:54:46.000000', NULL, 1),
(7290696, 1135998, 13077, '<td valign="top">Nice dramatic sky and well composed.</td>', 'Nice dramatic sky and well composed.', '2014-12-07 16:55:00.000000', NULL, 1),
(7290698, 1136215, 13077, '<td valign="top">Great light, it does have a dark and magical look to i.</td>', 'Great light, it does have a dark and magical look to i.', '2014-12-07 16:55:22.000000', NULL, 1),
(7290699, 1136435, 13077, '<td valign="top">Nicely caught action here.</td>', 'Nicely caught action here.', '2014-12-07 16:55:32.000000', NULL, 1),
(7290700, 1136306, 13077, '<td valign="top">He sure picked a nice place to rest and survey his domain, didn''t he.</td>', 'He sure picked a nice place to rest and survey his domain, didn''t he.', '2014-12-07 16:55:50.000000', NULL, 1),
(7290701, 1136460, 13077, '<td valign="top">Very nice, and interesting. I didn''t know trees grew in the middle of a lake.</td>', 'Very nice, and interesting. I didn''t know trees grew in the middle of a lake.', '2014-12-07 16:56:17.000000', NULL, 1),
(7290702, 1136291, 13077, '<td valign="top">Nice saying, and well illustrated. I like it.</td>', 'Nice saying, and well illustrated. I like it.', '2014-12-07 16:56:37.000000', NULL, 1),
(7290703, 1136377, 13077, '<td valign="top">Very nice atmosphere and the detail in the tree branches is great.</td>', 'Very nice atmosphere and the detail in the tree branches is great.', '2014-12-07 16:56:54.000000', NULL, 1),
(7290704, 1136407, 13077, '<td valign="top">I like this a lot. A LOT. I don''t know if it could have come together any better if you could freeze time and move the subjects around at will.<br/>Only minor nitpick is I would crop just a bit from the left to get rid of the shark fin antenna on the roof of the BMW.</td>', 'I like this a lot. A LOT. I don''t know if it could have come together any better if you could freeze time and move the subjects around at will.Only minor nitpick is I would crop just a bit from the left to get rid of the shark fin antenna on the roof of the BMW.', '2014-12-07 16:58:28.000000', NULL, 1),
(7290705, 1136394, 13077, '<td valign="top">He looks a bit out of focus, or maybe that''s just a glow added in the processing...</td>', 'He looks a bit out of focus, or maybe that''s just a glow added in the processing...', '2014-12-07 16:58:52.000000', NULL, 1),
(7290706, 1136321, 13077, '<td valign="top">Nice old fashioned look, and a good portrait with great lighting and eye contact.</td>', 'Nice old fashioned look, and a good portrait with great lighting and eye contact.', '2014-12-07 16:59:13.000000', NULL, 1),
(7290707, 1134976, 13077, '<td valign="top">The composition and range of colors is nice.</td>', 'The composition and range of colors is nice.', '2014-12-07 16:59:26.000000', NULL, 1),
(7290708, 1136477, 13077, '<td valign="top">A good looking bridge. Wonder what the story is.</td>', 'A good looking bridge. Wonder what the story is.', '2014-12-07 16:59:43.000000', NULL, 1),
(7290709, 1136117, 13077, '<td valign="top">It''s a cool mural, but I don''t think in taking the photo anything has been shown in its own light or any other spin has been put on the mural.</td>', 'It''s a cool mural, but I don''t think in taking the photo anything has been shown in its own light or any other spin has been put on the mural.', '2014-12-07 17:00:33.000000', NULL, 1),
(7290710, 1135843, 13077, '<td valign="top">Good detail both in the face and just enough in the background.</td>', 'Good detail both in the face and just enough in the background.', '2014-12-07 17:01:03.000000', NULL, 1),
(7290711, 1136267, 13077, '<td valign="top">Nicely caught action, good looking colors and good composition.</td>', 'Nicely caught action, good looking colors and good composition.', '2014-12-07 17:01:21.000000', NULL, 1),
(7290712, 1135911, 13077, '<td valign="top">Very nice sky, and good use of the buoys to add some interest to the bottom part.</td>', 'Very nice sky, and good use of the buoys to add some interest to the bottom part.', '2014-12-07 17:01:42.000000', NULL, 1),
(7290713, 1136378, 13077, '<td valign="top">I don''t get the title, also I don''t find the photo very interesting.</td>', 'I don''t get the title, also I don''t find the photo very interesting.', '2014-12-07 17:02:07.000000', NULL, 1),
(7290714, 1135328, 13077, '<td valign="top">Wow that''s a big wheel. The panning is well done.</td>', 'Wow that''s a big wheel. The panning is well done.', '2014-12-07 17:02:27.000000', NULL, 1),
