(7290718, 1136386, 13077, '<td valign="top">Well captured shadows and nicely composed.</td>', 'Well captured shadows and nicely composed.', '2014-12-07 17:03:48.000000', NULL, 1),
(7290719, 1136152, 13077, '<td valign="top">It''s a lot shinier than the other buildings, and I see he made sure to have a giant phallic symbol put on the top as well...</td>', 'It''s a lot shinier than the other buildings, and I see he made sure to have a giant phallic symbol put on the top as well...', '2014-12-07 17:04:50.000000', NULL, 1),
